      build: c => `https://103.79.184.97/api/music/url?source=tx&songId=${enc(c.id)}&quality=${HYW_Q[c.q] || '320k'}&key=6C1F-53W0-GRKI-EVFG`,
      parse: b => pickUrl(b),
