      name: 'ikun分享',
      build: c => `https://api.ikunshare.com/url?source=${c.platform}&songId=${enc(c.id)}&quality=${enc(c.q)}`,
      parse: b => (b && typeof b === 'object' && b.url) ? b.url : pickUrl(b),
