const SUB_INIT_TIMEOUT_MS = 30000
const SUB_REQUEST_TIMEOUT_MS = 12000
const TOTAL_TIMEOUT_MS = 45000
const VERIFY_TIMEOUT_MS = 8000
const COOLDOWN_MS = 30000
const PROBE_BYTES = 4096
const HAS_HOST_PROBE = !!(LX.utils && typeof LX.utils.audioProbe === 'function')
const HAS_STREAMING_FETCH = typeof HOST.fetch === 'function' && typeof HOST.AbortController === 'function' &&
  typeof HOST.ReadableStream === 'function' && HOST.ReadableStream.prototype &&
  typeof HOST.ReadableStream.prototype.getReader === 'function'

function sniffAudio(bytes) {
  if (!bytes || bytes.length < 4) return null
  const text = (offset, size) => String.fromCharCode(...Array.prototype.slice.call(bytes, offset, offset + size))
  if (bytes.length >= 10 && text(0, 3) === 'ID3' && bytes[3] >= 2 && bytes[3] < 5 && bytes[4] < 255 &&
    [6, 7, 8, 9].every(i => bytes[i] < 128)) return 'mp3(ID3)'
  if (bytes[0] === 255 && (bytes[1] & 246) === 240 && bytes.length >= 7 &&
    (bytes[2] >> 2 & 15) < 13) return 'aac'
  if (bytes[0] === 255 && (bytes[1] & 224) === 224 && (bytes[1] >> 3 & 3) !== 1 &&
    (bytes[1] >> 1 & 3) !== 0 && (bytes[2] >> 4) !== 15 && (bytes[2] >> 4) !== 0 &&
    (bytes[2] >> 2 & 3) !== 3) return 'mp3(frame)'
  if (text(0, 4) === 'fLaC') return 'flac'
  if (bytes.length >= 12 && text(0, 4) === 'RIFF' && text(8, 4) === 'WAVE') return 'wav'
  if (bytes.length >= 16 && text(4, 4) === 'ftyp') {
    const brands = []
    const boxSize = (bytes[0] * 16777216) + (bytes[1] << 16) + (bytes[2] << 8) + bytes[3]
    for (let i = 8; i + 4 <= Math.min(boxSize, bytes.length); i += 4) {
      if (i !== 12) brands.push(text(i, 4))
    }
    if (brands.some(b => ['M4A ', 'M4B ', 'M4P ', 'F4A ', 'F4B '].includes(b))) return 'm4a'
  }
  if (bytes.length >= 28 && text(0, 4) === 'OggS') {
    const offset = 27 + bytes[26]
    if (text(offset, 8) === 'OpusHead' || text(offset + 1, 6) === 'vorbis' ||
      text(offset, 8) === 'Speex   ' || text(offset + 1, 4) === 'FLAC') return 'ogg'
  }
  return null
}

function qualityMatchesAudio(quality, magic, bytes) {
  if (quality !== 'flac' && quality !== 'flac24bit') return true
  if (magic !== 'flac' || bytes.length < 42 || (bytes[4] & 127) !== 0 ||
    bytes[5] !== 0 || bytes[6] !== 0 || bytes[7] !== 34) return false
  const bitsPerSample = (((bytes[20] & 1) << 4) | (bytes[21] >> 4)) + 1
  return quality === 'flac' || bitsPerSample >= 24
}

function audioContentTypeAllowed(contentType) {
  return !/(?:^|\W)(?:text\/|video\/|application\/(?:json|[^;]*\+json|xml|[^;]*\+xml|javascript))/.test(contentType)
}

function canVerifyQuality(quality) {
  return (quality !== 'flac' && quality !== 'flac24bit') || HAS_STREAMING_FETCH || HAS_HOST_PROBE
}

function httpUrl(url) {
  if (typeof url !== 'string' || !/^https?:\/\/[^\s]+$/i.test(url)) return false
  if (HOST.URL) {
    try {
      const parsed = new HOST.URL(url)
      return !parsed.username && !parsed.password && /^(http|https):$/.test(parsed.protocol)
    } catch (_) { return false }
  }
  return !/^https?:\/\/[^/]*@/.test(url)
}

function disableEntry(entry, error) {
  entry.status = 'error'
  entry.error = error
  for (const id of entry.timers) { HOST.clearTimeout(id); HOST.clearInterval(id) }
  entry.timers.clear()
  for (const request of entry.requests) {
    request.active = false
    try { if (request.cancel) request.cancel() } catch (_) {}
  }
  entry.requests.clear()
}

function scopedEvaluator(scope) {
  with (scope) { return function(code) { return eval(code) } }
}

function loadEntry(sub, index) {
  const entry = { sub, handlers: [], declared: {}, status: 'pending', timers: new Set(), requests: new Set(), cooldowns: new Map() }
  entry.ready = new Promise(resolve => {
    let settled = false
    const finish = error => {
      if (settled) return
      settled = true
      HOST.clearTimeout(initTimer)
      if (error) disableEntry(entry, error)
      else entry.status = 'ready'
      resolve(entry)
    }
    const callbackError = error => {
      // A callback for one song must not disable every platform or cancel other songs.
      entry.error = error
      if (!settled) finish(error)
    }
    const shim = {
      version: LX.version, env: LX.env, platform: LX.platform, EVENT_NAMES, utils: LX.utils,
      currentScriptInfo: { name: sub.name, version: sub.version, description: sub.description,
        author: sub.author, homepage: sub.homepage, rawScript: sub.code },
      on(event, handler) {
        if (entry.status !== 'error' && event === EVENT_NAMES.request && typeof handler === 'function') entry.handlers.push(handler)
      },
      send(event, data) {
        if (event === EVENT_NAMES.inited && !settled) {
          const declared = data && data.sources || {}
          for (const platform of Object.keys(sub.healthy)) {
            if (declared[platform] && Array.isArray(declared[platform].qualitys)) entry.declared[platform] = declared[platform]
          }
          finish()
        }
        // A subsource's update URL must not replace the entire merged source.
        return Promise.resolve()
      },
      request(url, options, callback) {
        if (typeof options === 'function') { callback = options; options = {} }
        if (entry.status === 'error') return function() {}
        const pending = { active: true, cancel: null }
        entry.requests.add(pending)
        const opts = Object.assign({}, options || {})
        opts.timeout = Math.min(Number(opts.timeout) > 0 ? Number(opts.timeout) : SUB_REQUEST_TIMEOUT_MS, SUB_REQUEST_TIMEOUT_MS)
        try {
          pending.cancel = LX.request(url, opts, function(error, response, body) {
            if (!pending.active || entry.status === 'error') return
            pending.active = false
            entry.requests.delete(pending)
            try {
              const result = callback.call(world, error, response, body)
              if (result && typeof result.catch === 'function') result.catch(callbackError)
            } catch (err) { callbackError(err) }
          })
        } catch (err) { entry.requests.delete(pending); throw err }
        return function() {
          pending.active = false
          entry.requests.delete(pending)
          if (pending.cancel) pending.cancel()
        }
      },
    }
    const world = Object.create(null)
    for (const key of ['Array', 'Object', 'String', 'Number', 'Boolean', 'Math', 'Date', 'JSON', 'RegExp',
      'Promise', 'Error', 'TypeError', 'Map', 'Set', 'WeakMap', 'WeakSet', 'Symbol', 'Proxy', 'Reflect',
      'Uint8Array', 'ArrayBuffer', 'DataView', 'Buffer', 'URL', 'URLSearchParams', 'TextEncoder', 'TextDecoder',
      'atob', 'btoa', 'parseInt', 'parseFloat', 'isNaN', 'isFinite', 'encodeURIComponent', 'decodeURIComponent',
      'encodeURI', 'decodeURI', 'console', 'NaN', 'Infinity', 'undefined']) world[key] = HOST[key]
    world.lx = shim
    entry.world = world
    world.globalThis = world
    world.window = world
    world.self = world
    world.global = world
    const scope = new Proxy(world, {
      // Direct eval must retain the source function's own lexical variables.
      has: (_, key) => typeof key === 'string' && key !== 'eval',
      get: (target, key) => key === Symbol.unscopables ? undefined : target[key],
    })
    const compile = (params, code) => NativeFunction('scope', 'eval',
      'with (scope) { return (function(' + params.join(',') + ') {\n' + code + '\n}) }')(scope, nativeEval)
    world.Function = function() {
      const args = Array.prototype.slice.call(arguments).map(String)
      const compiled = compile(args.slice(0, -1), args.length ? args[args.length - 1] : '')
      return function() { return compiled.apply(world, arguments) }
    }
    const scopedEval = scopedEvaluator(scope)
    world.eval = code => scopedEval.call(world, String(code))
    const schedule = (callback, delay, repeat, args) => {
      if (entry.status === 'error') return null
      if (entry.timers.size >= 256) throw new Error('Subsource timer quota exceeded')
      const run = function() {
        if (!repeat) entry.timers.delete(id)
        if (entry.status === 'error') return
        try {
          const result = callback.apply(world, args)
          if (result && typeof result.catch === 'function') result.catch(callbackError)
        } catch (err) { callbackError(err) }
      }
      const id = repeat ? HOST.setInterval(run, Math.max(10, Number(delay) || 0)) : HOST.setTimeout(run, Number(delay) || 0)
      entry.timers.add(id)
      return id
    }
    world.setTimeout = (fn, ms, ...args) => schedule(fn, ms, false, args)
    world.setInterval = (fn, ms, ...args) => schedule(fn, ms, true, args)
    world.clearTimeout = world.clearInterval = id => {
      HOST.clearTimeout(id); HOST.clearInterval(id); entry.timers.delete(id)
    }
    const initTimer = HOST.setTimeout(() => finish(new Error('Subsource initialization timeout')), SUB_INIT_TIMEOUT_MS)
    // The host can disable eval/Function; ordinary subsources must not need either.
    try { SUB_RUNNERS[index].call(world, scope) }
    catch (error) { disableEntry(entry, error); finish(error) }
  })
  return entry
}

async function verifyWithFetch(url, quality, timeoutMs, control) {
  const controller = new HOST.AbortController()
  control.cancel = () => controller.abort()
  const timer = HOST.setTimeout(() => controller.abort(), timeoutMs)
  let reader
  try {
    const response = await HOST.fetch(url, { headers: { Range: 'bytes=0-' + (PROBE_BYTES - 1) }, signal: controller.signal })
    if (response.status !== 200 && response.status !== 206) throw new Error('Playback HTTP ' + response.status)
    const contentType = String(response.headers.get('content-type') || '').toLowerCase()
    if (!audioContentTypeAllowed(contentType)) throw new Error('Playback content type is not audio')
    if (!response.body || typeof response.body.getReader !== 'function') throw new Error('Streaming body unavailable')
    reader = response.body.getReader()
    const bytes = new Uint8Array(PROBE_BYTES)
    let size = 0
    while (size < PROBE_BYTES) {
      const result = await reader.read()
      if (result.done) break
      const part = result.value.subarray(0, PROBE_BYTES - size)
      bytes.set(part, size)
      size += part.length
    }
    const prefix = bytes.subarray(0, size)
    const magic = sniffAudio(prefix)
    if (!magic || !qualityMatchesAudio(quality, magic, prefix)) throw new Error('Playback audio/quality verification failed')
  } finally {
    HOST.clearTimeout(timer)
    controller.abort()
    control.cancel = null
    if (reader) { try { Promise.resolve(reader.cancel()).catch(() => {}) } catch (_) {} }
  }
}

// lxserver can expose a bounded broker without granting scripts a general fetch API.
function verifyWithHostProbe(url, quality, timeoutMs, control) {
  return new Promise((resolve, reject) => {
    let cancel, settled = false
    const finish = error => {
      if (settled) return
      settled = true
      control.cancel = null
      HOST.clearTimeout(timer)
      if (cancel) { try { cancel() } catch (_) {} }
      if (error) reject(error)
      else resolve()
    }
    const timer = HOST.setTimeout(() => finish(new Error('Playback probe timeout')), timeoutMs)
    control.cancel = () => finish(new Error('Playback probe cancelled'))
    try {
      cancel = LX.utils.audioProbe(url, { timeout: timeoutMs, maxBytes: PROBE_BYTES }, (error, response) => {
        if (error) { finish(error); return }
        try {
          if (!response || (response.statusCode !== 200 && response.statusCode !== 206)) {
            throw new Error('Playback HTTP ' + (response && response.statusCode))
          }
          if (!audioContentTypeAllowed(String(response.contentType || '').toLowerCase())) {
            throw new Error('Playback content type is not audio')
          }
          const prefix = new Uint8Array(response.bytes || [])
          const magic = sniffAudio(prefix)
          if (!magic || !qualityMatchesAudio(quality, magic, prefix)) {
            throw new Error('Playback audio/quality verification failed')
          }
          finish()
        } catch (error) { finish(error) }
      })
      if (settled && cancel) cancel()
    } catch (error) { finish(error) }
  })
}

// Limited LX hosts buffer lx.request bodies. HEAD is a connectivity check, not
// evidence of a codec. Binary MIME or lack of HEAD support is inconclusive for
// ordinary audio; only a byte-capable host advertises lossless qualities.
function verifyWithHead(url, quality, timeoutMs, control) {
  if (!canVerifyQuality(quality)) return Promise.reject(new Error('Lossless audio requires a bounded byte probe'))
  return new Promise((resolve, reject) => {
    let cancel, settled = false
    const finish = error => {
      if (settled) return
      settled = true
      control.cancel = null
      HOST.clearTimeout(timer)
      if (cancel) { try { cancel() } catch (_) {} }
      if (error) reject(error)
      else resolve()
    }
    const timer = HOST.setTimeout(() => finish(new Error('Playback probe timeout')), timeoutMs)
    control.cancel = () => finish(new Error('Playback probe cancelled'))
    try {
      cancel = LX.request(url, { method: 'HEAD', timeout: timeoutMs }, (error, response) => {
        if (error) { finish(error); return }
        const status = response && response.statusCode
        const headers = response && response.headers || {}
        const ct = String(headers['content-type'] || headers['Content-Type'] || '').toLowerCase()
        if (status === 405 || status === 501) { finish(); return }
        if (status !== 200 && status !== 206) { finish(new Error('Playback HTTP ' + status)); return }
        if (!audioContentTypeAllowed(ct) || (ct && !/^(?:audio\/|application\/(?:octet-stream|binary)(?:\s*;|$)|binary\/octet-stream(?:\s*;|$))/.test(ct))) {
          finish(new Error('Playback content type is not audio')); return
        }
        finish()
      })
      if (settled && cancel) cancel()
    } catch (error) { finish(error) }
  })
}

async function verifyPlayback(url, quality, timeoutMs, control) {
  if (!httpUrl(url)) throw new Error('Invalid playback URL')
  if (HAS_HOST_PROBE) {
    await verifyWithHostProbe(url, quality, timeoutMs, control)
  } else if (HAS_STREAMING_FETCH) {
    await verifyWithFetch(url, quality, timeoutMs, control)
  } else await verifyWithHead(url, quality, timeoutMs, control)
}

const ENTRIES = SUBS.map(loadEntry)

async function withDeadline(work, timeoutMs, control, message) {
  if (timeoutMs <= 0) throw new Error('Playback total timeout')
  let timer
  try {
    return await Promise.race([
      Promise.resolve().then(work),
      new Promise((_, reject) => {
        timer = HOST.setTimeout(() => {
          control.active = false
          if (control.cancel) control.cancel()
          reject(new Error(message))
        }, timeoutMs)
      }),
    ])
  } finally { HOST.clearTimeout(timer) }
}

LX.on(EVENT_NAMES.request, async ({ source, action, info }) => {
  if (action !== 'musicUrl') throw new Error('Only musicUrl is supported')
  const quality = info && info.type || '320k'
  if (!SOURCES[source] || !SOURCES[source].qualitys.includes(quality)) throw new Error('Platform/quality was not health-verified')
  if (!canVerifyQuality(quality)) throw new Error('Lossless audio requires a bounded byte probe on this host; select 320k or install the lxserver audio probe')
  const started = Date.now()
  const errors = []
  const key = source + ':' + quality
  // Recent failures lose priority only for this platform/quality. They remain a last
  // resort for a different song, and regain their normal priority after cooldown.
  const candidates = ENTRIES.filter(entry => entry.status === 'ready' && entry.sub.healthy[source] &&
    entry.sub.healthy[source].includes(quality) && entry.declared[source] &&
    entry.declared[source].qualitys.includes(quality) && entry.handlers[0])
    .sort((a, b) => Number((a.cooldowns.get(key) || 0) > started) - Number((b.cooldowns.get(key) || 0) > started) ||
      ((b.sub.reliability && b.sub.reliability[source] && b.sub.reliability[source][quality]) || 0) -
      ((a.sub.reliability && a.sub.reliability[source] && a.sub.reliability[source][quality]) || 0))
  const remaining = () => TOTAL_TIMEOUT_MS - (Date.now() - started)
  for (const entry of candidates) {
    if (remaining() <= 0) break
    const control = { cancel: null, active: true }
    try {
      const url = await withDeadline(() => entry.handlers[0].call(entry.world, { source, action, info: {
          type: quality, musicInfo: JSON.parse(JSON.stringify(info && info.musicInfo || {})),
        } }), Math.min(SUB_REQUEST_TIMEOUT_MS, remaining()), control, 'Subsource request timeout')
      if (!control.active || entry.status !== 'ready') throw new Error('Subsource request expired')
      const verifyTimeout = Math.min(VERIFY_TIMEOUT_MS, remaining())
      await withDeadline(() => verifyPlayback(url, quality, verifyTimeout, control), verifyTimeout,
        control, 'Playback probe timeout')
      entry.cooldowns.delete(key)
      return url
    } catch (error) {
      entry.cooldowns.set(key, Date.now() + COOLDOWN_MS)
      errors.push(entry.sub.name + ': ' + String(error && error.message || error).slice(0, 120))
    }
    finally {
      control.active = false
      if (control.cancel) control.cancel()
    }
  }
  throw new Error('All embedded sources failed: ' + (errors.join(' | ') || 'no verified live source'))
})

Promise.all(ENTRIES.map(entry => entry.ready)).then(() => {
  const sources = {}
  for (const platform of Object.keys(SOURCES)) {
    const qualitys = SOURCES[platform].qualitys.filter(quality => canVerifyQuality(quality) && ENTRIES.some(entry => entry.status === 'ready' &&
      entry.sub.healthy[platform] && entry.sub.healthy[platform].includes(quality) && entry.declared[platform] &&
      entry.declared[platform].qualitys.includes(quality) && entry.handlers.length))
    if (qualitys.length) sources[platform] = Object.assign({}, SOURCES[platform], { qualitys })
  }
  if (!Object.keys(sources).length) throw new Error('No embedded sources initialized successfully')
  return LX.send(EVENT_NAMES.inited, { sources })
})
